use sqlx::{Pool, Postgres};

use crate::{
    internal_events::EndpointBytesSent,
    sinks::{prelude::*, util::retries::RetryAction},
};

#[derive(Clone)]
pub struct PostgresRetryLogic;

impl RetryLogic for PostgresRetryLogic {
    type Error = sqlx::Error;
    type Response = PostgresResponse;

    fn is_retriable_error(&self, error: &Self::Error) -> bool {
        // Retry on transient errors such as I/O failures, closed/timed-out pool
        // connections, or protocol errors. Database errors (e.g. constraint
        // violations, unknown tables) are not retriable.
        matches!(
            error,
            sqlx::Error::Io(_)
                | sqlx::Error::PoolTimedOut
                | sqlx::Error::PoolClosed
                | sqlx::Error::WorkerCrashed
                | sqlx::Error::Protocol(_)
                | sqlx::Error::Tls(_)
        )
    }

    fn should_retry_response(&self, _response: &Self::Response) -> RetryAction {
        RetryAction::Successful
    }
}

#[derive(Clone)]
pub struct PostgresService {
    connection_pool: Pool<Postgres>,
    table: String,
    endpoint: String,
}

impl PostgresService {
    pub const fn new(connection_pool: Pool<Postgres>, table: String, endpoint: String) -> Self {
        Self {
            connection_pool,
            table,
            endpoint,
        }
    }
}

#[derive(Clone)]
pub struct PostgresRequest {
    /// The batch of events serialized into a single JSON array.
    pub body: Value,
    pub finalizers: EventFinalizers,
    pub metadata: RequestMetadata,
}

impl TryFrom<Vec<Event>> for PostgresRequest {
    type Error = serde_json::Error;

    fn try_from(mut events: Vec<Event>) -> Result<Self, Self::Error> {
        let finalizers = events.take_finalizers();
        let metadata_builder = RequestMetadataBuilder::from_events(&events);

        // Serialize the batch of events into a single JSON array, which can then
        // be expanded into rows on the PostgreSQL server via
        // `jsonb_populate_recordset`.
        let body = serde_json::to_value(&events)?;
        let request_size = serde_json::to_vec(&body)?.len();
        let request_size =
            NonZeroUsize::new(request_size).unwrap_or_else(|| NonZeroUsize::new(1).unwrap());
        let metadata = metadata_builder.with_request_size(request_size);

        Ok(Self {
            body,
            finalizers,
            metadata,
        })
    }
}

impl Finalizable for PostgresRequest {
    fn take_finalizers(&mut self) -> EventFinalizers {
        self.finalizers.take_finalizers()
    }
}

impl MetaDescriptive for PostgresRequest {
    fn get_metadata(&self) -> &RequestMetadata {
        &self.metadata
    }

    fn metadata_mut(&mut self) -> &mut RequestMetadata {
        &mut self.metadata
    }
}

pub struct PostgresResponse {
    metadata: RequestMetadata,
}

impl DriverResponse for PostgresResponse {
    fn event_status(&self) -> EventStatus {
        EventStatus::Delivered
    }

    fn events_sent(&self) -> &GroupedCountByteSize {
        self.metadata.events_estimated_json_encoded_byte_size()
    }

    fn bytes_sent(&self) -> Option<usize> {
        Some(self.metadata.request_encoded_size())
    }
}

impl Service<PostgresRequest> for PostgresService {
    type Response = PostgresResponse;
    type Error = sqlx::Error;
    type Future = BoxFuture<'static, Result<Self::Response, Self::Error>>;

    fn poll_ready(&mut self, _cx: &mut Context) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    fn call(&mut self, request: PostgresRequest) -> Self::Future {
        let service = self.clone();

        Box::pin(async move {
            let metadata = request.metadata;
            let byte_size = metadata.request_encoded_size();

            let table = &service.table;
            // Bind the serialized JSON array as text and cast it to `jsonb` on the
            // server, expanding it into rows matching the target table's columns.
            let statement = format!(
                "INSERT INTO {table} SELECT * FROM jsonb_populate_recordset(NULL::{table}, $1::jsonb)"
            );
            sqlx::query(&statement)
                .bind(request.body.to_string())
                .execute(&service.connection_pool)
                .await?;

            emit!(EndpointBytesSent {
                byte_size,
                protocol: "postgres",
                endpoint: &service.endpoint,
            });

            Ok(PostgresResponse { metadata })
        })
    }
}
